draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // stick figure
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // question mark
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2 - 20, 10, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 50, H/2 - 10);
  ctx.lineTo(W/2 + 50, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 + 50, H/2 + 20, 10, 0, Math.PI);
  ctx.stroke();

  // creating own meaning
  ctx.beginPath();
  ctx.moveTo(W/2 + 80, H/2);
  ctx.lineTo(W/2 + 80 + 30 * Math.sin(t), H/2 + 30 * Math.cos(t));
  ctx.stroke();

  ctx.restore();
}
